-- data/sample/views.sql: DuckDB views over the sample bundle, the names the twins query.
-- GENERATED by `python -m data.generator.sample`. Paths resolve against file_search_path = data/sample.
-- v_crime_unified mirrors zetaris/10_views.sql: Supabase + legacy CCTNS CSVs + archive parquet.
CREATE OR REPLACE VIEW v_crime_unified AS
WITH codes AS (
  SELECT ipc_code AS code FROM 'sb/section_map.parquet' WHERE ipc_code IS NOT NULL
  UNION SELECT bns_code FROM 'sb/section_map.parquet' WHERE bns_code IS NOT NULL),
cats AS (SELECT sub_type, category FROM read_csv('ref/crime_types.csv', header = true, all_varchar = true)),
st AS (SELECT station_id, lower(split_part(name, ' (', 1)) AS locality FROM 'sb/stations.parquet'),
cctns AS (SELECT * FROM read_csv('legacy/cctns_*.csv', all_varchar = true, header = true)),
arc AS (SELECT * FROM 'legacy/archive.parquet'),
cctns_unmapped AS (
  SELECT rid, max(CASE WHEN k.code IS NULL THEN 1 ELSE 0 END) AS unmapped
  FROM (SELECT PS_CODE || ':' || FIR_NUM AS rid, trim(unnest(string_split(ACT_SEC, ','))) AS tok FROM cctns) t
  LEFT JOIN codes k ON k.code = t.tok GROUP BY rid),
archive_unmapped AS (
  SELECT case_ref, max(CASE WHEN k.code IS NULL THEN 1 ELSE 0 END) AS unmapped
  FROM (SELECT case_ref, trim(unnest(string_split(ipc_sections, ';'))) AS tok FROM arc) t
  LEFT JOIN codes k ON k.code = CASE WHEN t.tok LIKE 'BNS%' THEN t.tok ELSE 'IPC ' || t.tok END
  GROUP BY case_ref)
SELECT crime_id, source, source_row_id, station_id, fir_no, category, sub_type, sections, occurred_from, occurred_to, reported_at, lat, lon, address, ward_no, h3_r9, h3_r8, geohash7, week, severity, property, weapon, offenders_described, victims, status, narrative, CAST(NULL AS VARCHAR) AS sections_raw, synthetic
FROM 'sb/crimes.parquet'
UNION ALL
SELECT 'CCTNS-' || c.PS_CODE || '-' || replace(c.FIR_NUM, '/', '-'), 's3csv.cctns', c.PS_CODE || ':' || c.FIR_NUM,
       s.station_id, c.FIR_NUM, m.category, lower(replace(c.MINOR_HEAD, ' ', '_')), NULL,
       timezone('Asia/Kolkata', strptime(c.OCC_DT_FROM, '%d-%m-%Y %H:%M')),
       timezone('Asia/Kolkata', strptime(c.OCC_DT_TO, '%d-%m-%Y %H:%M')),
       timezone('Asia/Kolkata', strptime(c.FIR_DT || ' 23:59:59', '%d-%m-%Y %H:%M:%S')),
       CAST(c.LAT AS DOUBLE), CAST(c.LONG AS DOUBLE), c.PLACE_OCC, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
       NULL, NULL, 'legacy', c.BRIEF_FACTS, CASE WHEN u.unmapped = 1 THEN c.ACT_SEC END, true
FROM cctns c
LEFT JOIN st s ON s.locality = lower(trim(string_split(c.PLACE_OCC, ',')[-1]))
LEFT JOIN cats m ON m.sub_type = lower(replace(c.MINOR_HEAD, ' ', '_'))
LEFT JOIN cctns_unmapped u ON u.rid = c.PS_CODE || ':' || c.FIR_NUM
UNION ALL
SELECT a.case_ref, 's3pq.archive', a.case_ref, s.station_id, NULL, m.category, a.crime_subhead, NULL,
       timezone('Asia/Kolkata', strptime(a.date_of_occurrence || lpad(a.time_of_occurrence, 4, '0'), '%Y%m%d%H%M')),
       NULL, NULL, a.latitude, a.longitude, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
       a.disposal, NULL, CASE WHEN u.unmapped = 1 THEN a.ipc_sections END, true
FROM arc a
LEFT JOIN st s ON s.locality = lower(a.station_name)
LEFT JOIN cats m ON m.sub_type = a.crime_subhead
LEFT JOIN archive_unmapped u ON u.case_ref = a.case_ref;
